before:
Complete local Rust example; the app itself does not execute it:
```rust
use std::cell::RefCell;

fn main() {
    let value = RefCell::new(3);
    let read = value.borrow();
    println!("{}", value.try_borrow_mut().is_err());
    drop(read);
    *value.borrow_mut() = 9;
    println!("{}", value.borrow());
}
```

